public long modInverseBruteForce(long a, long m) {
    a = ((a % m) + m) % m;
    for (long x = 1; x < m; x++) {
        if ((a * x) % m == 1) {
            return x;
        }
    }
    return -1; // no inverse (gcd(a, m) != 1)
}

