// Returns {g, x, y} with a*x + b*y = g = gcd(a, b).
public long[] extgcd(long a, long b) {
    if (b == 0) {
        return new long[]{a, 1, 0};
    }
    long[] r = extgcd(b, a % b);
    long g = r[0], x1 = r[1], y1 = r[2];
    long x = y1;
    long y = x1 - (a / b) * y1;
    return new long[]{g, x, y};
}

// Modular inverse of a mod m, or -1 if none (gcd != 1).
public long modInverse(long a, long m) {
    long[] r = extgcd(((a % m) + m) % m, m);
    if (r[0] != 1) return -1;        // no inverse
    return ((r[1] % m) + m) % m;     // normalise into [0, m)
}

code.python:
def extgcd(self, a: int, b: int) -> tuple[int, int, int]:
    # Returns (g, x, y) with a*x + b*y = g = gcd(a, b).
    if b == 0:
        return (a, 1, 0)
    g, x1, y1 = self.extgcd(b, a % b)
    x = y1
    y = x1 - (a // b) * y1
    return (g, x, y)

def mod_inverse(self, a: int, m: int) -> int:
    g, x, _ = self.extgcd(a % m, m)
    if g != 1:
        return -1            # no inverse: gcd(a, m) != 1
    return (x % m + m) % m   # normalise into [0, m)

